SELECT d, n FROM (SELECT ci.name AS d, COUNT(o.order_id) AS n, RANK() OVER (ORDER BY COUNT(o.order_id) DESC) AS rk FROM orders o JOIN customer_addresses a USING (address_id) JOIN cities ci ON ci.city_id = a.city_id WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2024-07-01 00:00:00' AND o.order_at < TIMESTAMP '2024-10-01 00:00:00' GROUP BY ci.name) t WHERE rk <= 5 ORDER BY n DESC
